<?xml version="1.0" encoding="UTF-8"?><map version="1.0.1"><node TEXT="数据整理课程"><node TEXT="课程一｜数据整理"><node TEXT="基础流程：设计 → 审核 → 分组汇总 → 展示 → 归档"></node><node TEXT="统计分组：组内同质、组间差异；穷尽与互斥"></node><node TEXT="分组方法：品质 / 数量；平行 / 复合"></node><node TEXT="分配数列：品质、单项、组距"></node><node TEXT="整理规范：真实、一致、可靠"></node></node><node TEXT="课程二｜简单数据"><node TEXT="直方图：看分布、看波动、定位改进重点"></node><node TEXT="绘制：极差 → 组数 → 组距 → 组界 → 频数 → 图形"></node><node TEXT="形态分析：正常、折齿、缓坡、孤岛、双峰、绝壁"></node><node TEXT="分组整理：选标志、划界限"></node><node TEXT="层别整理：按来源分类，以人机物法环排查原因"></node></node><node TEXT="课程三｜复杂数据"><node TEXT="相关分析：判断关系方向与强弱"></node><node TEXT="相关系数：−1≤r≤1；看符号与绝对值"></node><node TEXT="Excel案例：访问量与营业额 r≈0.999835"></node><node TEXT="回归分析：建模 → 估参 → 检验 → 预测"></node><node TEXT="一元模型：Yᵢ＝β₀＋β₁Xᵢ＋μᵢ"></node><node TEXT="辨析：相关看密切程度，回归估计数量关系"></node></node></node></map>